import 'package:cloud_firestore/cloud_firestore.dart';

class QuestionOption { const QuestionOption({required this.id, required this.text, required this.scores}); final String id, text; final Map<String, double> scores; factory QuestionOption.fromMap(Map<String, dynamic> map) => QuestionOption(id: map['id'] as String? ?? '', text: map['text'] as String? ?? '', scores: (map['scores'] as Map<String, dynamic>? ?? const {}).map((key, value) => MapEntry(key, (value as num).toDouble()))); Map<String, Object> toMap() => {'id': id, 'text': text, 'scores': scores}; }
class QuestionModel { const QuestionModel({required this.id, required this.assessmentId, required this.text, required this.options, required this.order}); final String id, assessmentId, text; final List<QuestionOption> options; final int order; factory QuestionModel.fromFirestore(DocumentSnapshot<Map<String, dynamic>> doc) => QuestionModel.fromMap(doc.id, doc.data() ?? const {}); factory QuestionModel.fromMap(String id, Map<String, dynamic> map) => QuestionModel(id: id, assessmentId: map['assessmentId'] as String? ?? '', text: map['text'] as String? ?? '', order: (map['order'] as num?)?.toInt() ?? 0, options: (map['options'] as List? ?? const []).map((item) => QuestionOption.fromMap(Map<String, dynamic>.from(item as Map))).toList()); Map<String, Object> toMap() => {'assessmentId': assessmentId, 'text': text, 'order': order, 'options': options.map((item) => item.toMap()).toList()}; }
